import { Input } from "./types";
import { PoseInFrame } from "@foxglove/schemas";
export const inputs = ["/odom"];
export const output = "/studio_script/odom_pose";
export default function script(event: Input<"/odom">): PoseInFrame {
  const m = event.message;
  const st = m.header.stamp as { sec: number; nanosec?: number; nsec?: number };
  return { timestamp: { sec: st.sec, nsec: st.nanosec ?? st.nsec ?? 0 }, frame_id: m.header.frame_id, pose: m.pose.pose };
}

