import { Input } from "./types";
import { PosesInFrame, Pose } from "@foxglove/schemas";
export const inputs = ["/odom"];
export const output = "/studio_script/odom_path";
const MIN_STEP = 0.02, MAX_POINTS = 5000;
const poses: Pose[] = [];
export default function script(event: Input<"/odom">): PosesInFrame | undefined {
  const m = event.message, p = m.pose.pose, last = poses[poses.length - 1];
  if (last && Math.hypot(p.position.x - last.position.x, p.position.y - last.position.y) < MIN_STEP) return undefined;
  poses.push(p); if (poses.length > MAX_POINTS) poses.shift();
  const st = m.header.stamp as { sec: number; nanosec?: number; nsec?: number };
  return { timestamp: { sec: st.sec, nsec: st.nanosec ?? st.nsec ?? 0 }, frame_id: m.header.frame_id, poses };
}

