import { Input } from "./types";
export const inputs = ["/battery_state"];
export const output = "/studio_script/battery";
type Output = { voltage: number; percentage: number; low: boolean };
export default function script(event: Input<"/battery_state">): Output {
  const m = event.message;
  const pct = m.percentage <= 1 ? m.percentage * 100 : m.percentage; // 0..1 of 0..100
  return { voltage: Math.round(m.voltage * 100) / 100, percentage: Math.round(pct), low: m.voltage < 11.2 || pct < 50 };
}
